    'import java.util.List;',
    'import java.util.Map;',
    'import java.util.Optional;',
    'import java.util.concurrent.ConcurrentHashMap;',
    'import java.util.concurrent.atomic.AtomicLong;',
    'import org.springframework.stereotype.Component;',
    '',
    '/** In-memory item store. */',
    '@Component',
    'public class ItemStore {',
    '  private final AtomicLong sequence = new AtomicLong();',
    '  private final Map<Long, Item> items = new ConcurrentHashMap<>();',
    '',
    '  /** Lists all items. */',
    '  public List<Item> list() { return new ArrayList<>(items.values()); }',
    '',
    '  /** Finds an item by id. */',
    '  public Optional<Item> get(long id) { return Optional.ofNullable(items.get(id)); }',
    '',
    '  /** Creates an item. */',
    '  public Item create(String name, String description) {',
    '    long id = sequence.incrementAndGet();',
    '    Item item = new Item(id, name, description);',
    '    items.put(id, item);',
    '    return item;',
    '  }',
    '',
    '  /** Updates an item. */',
    '  public Optional<Item> update(long id, String name, String description) {',
    '    if (!items.containsKey(id)) {',
    '      return Optional.empty();',
    '    }',
    '    Item item = new Item(id, name, description);',
    '    items.put(id, item);',
    '    return Optional.of(item);',
    '  }',
    '',
    '  /** Deletes an item. */',
    '  public boolean delete(long id) { return items.remove(id) != null; }',
    '',
    '  /** Clears all items for tests. */',
    '  public void clear() {',
    '    items.clear();',
    '    sequence.set(0);',
    '  }',
    '}',
