    '    mockMvc.perform(post("/api/items").contentType(MediaType.APPLICATION_JSON).content("{\\"name\\":\\"demo\\"}"));',
    '    mockMvc.perform(delete("/api/items/1")).andExpect(status().isNoContent());',
